INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',6,'Part 6 — Cấp 1','[READING_PART6_LEVEL:1] Chọn đủ 4 câu của bài đọc để xem kết quả.','EASY',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%');
INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%' ORDER BY id LIMIT 1),'{"title": "Office Welcome Session", "lines": [{"en": "To: New employees · Subject: Welcome session", "vi": "Gửi: Nhân viên mới · Chủ đề: Buổi chào đón"}, {"en": "Our welcome session [131] at 9 a.m. every Monday. Please arrive ten minutes early.", "vi": "Buổi chào đón của chúng tôi bắt đầu lúc 9 giờ sáng thứ Hai hằng tuần. Vui lòng đến sớm mười phút."}, {"en": "The session takes place [132] Room 204. Bring your employee badge.", "vi": "Buổi chào đón diễn ra tại phòng 204. Hãy mang theo thẻ nhân viên."}, {"en": "Our team will explain the safety rules [133]. There will be time for questions at the end.", "vi": "Nhóm chúng tôi sẽ giải thích rõ ràng các quy định an toàn. Cuối buổi sẽ có thời gian dành cho câu hỏi."}, {"en": "[134] We look forward to meeting you on Monday.", "vi": "Vui lòng xác nhận tham dự bằng cách trả lời email này. Chúng tôi mong được gặp bạn vào thứ Hai."}], "glossary": {"session": "buổi học; phiên họp", "employees": "nhân viên", "badge": "thẻ nhân viên", "safety": "sự an toàn", "attendance": "sự tham dự", "confirm": "xác nhận", "arrive": "đến"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Chọn đáp án cho chỗ trống [131]','{"options_vi": {"A": "bắt đầu (nguyên mẫu)", "B": "bắt đầu (ngôi thứ ba số ít)", "C": "đang bắt đầu", "D": "để bắt đầu"}, "explanation": "Every Monday chỉ thói quen. Chủ ngữ session số ít nên dùng begins; beginning và to begin không làm động từ chính chia thì."}',131 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:1]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=131);
