INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',6,'Part 6 — Cấp 2','[READING_PART6_LEVEL:2] Chọn đủ 4 câu của bài đọc để xem kết quả.','EASY',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%');
INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1),'{"title": "Updated Delivery Schedule", "lines": [{"en": "To: Store managers · From: Distribution team", "vi": "Gửi: Quản lý cửa hàng · Từ: Nhóm phân phối"}, {"en": "Because our warehouse is being repaired, deliveries [131] from the temporary facility next week.", "vi": "Vì kho đang được sửa chữa, các chuyến hàng sẽ được gửi từ cơ sở tạm thời vào tuần tới."}, {"en": "Please check your order [132] before submitting it. Changes cannot be made after dispatch.", "vi": "Vui lòng kiểm tra kỹ đơn hàng trước khi gửi. Không thể thay đổi sau khi hàng được gửi đi."}, {"en": "We have worked with the same courier [133] 2021, and its drivers know all our stores.", "vi": "Chúng tôi đã hợp tác với cùng một đơn vị chuyển phát từ năm 2021 và các tài xế biết tất cả cửa hàng của chúng tôi."}, {"en": "[134] You can use that number to follow the progress of your delivery online.", "vi": "Một mã theo dõi sẽ được gửi qua email khi đơn hàng rời kho. Bạn có thể dùng mã đó để theo dõi tiến trình giao hàng trên mạng."}], "glossary": {"warehouse": "nhà kho", "deliveries": "các chuyến giao hàng", "temporary": "tạm thời", "facility": "cơ sở", "courier": "đơn vị chuyển phát", "dispatch": "việc gửi hàng", "tracking": "việc theo dõi"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Chọn đáp án cho chỗ trống [131]','{"options_vi": {"A": "sẽ gửi", "B": "sẽ được gửi", "C": "đang gửi", "D": "để gửi"}, "explanation": "Deliveries nhận hành động gửi; next week chỉ tương lai. Cấu trúc bị động tương lai là will be sent. Will send mang nghĩa chủ động."}',131 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:2]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=131);
