INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',6,'Part 6 — Cấp 3','[READING_PART6_LEVEL:3] Chọn đủ 4 câu của bài đọc để xem kết quả.','MEDIUM',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%');
INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%' ORDER BY id LIMIT 1),'{"title": "Conference Registration", "lines": [{"en": "Annual Business Conference · Registration notice", "vi": "Hội nghị kinh doanh thường niên · Thông báo đăng ký"}, {"en": "[131] the limited number of seats, early registration is strongly recommended.", "vi": "Do số lượng chỗ ngồi hạn chế, việc đăng ký sớm rất được khuyến khích."}, {"en": "Participants [132] register before June 1 will receive a discount. Payment must be completed online.", "vi": "Những người tham dự đăng ký trước ngày 1 tháng 6 sẽ được giảm giá. Việc thanh toán phải hoàn tất trực tuyến."}, {"en": "By the time the conference opens, the organizers [133] all presentation materials.", "vi": "Trước lúc hội nghị khai mạc, ban tổ chức sẽ đã chuẩn bị xong toàn bộ tài liệu thuyết trình."}, {"en": "[134] Please show this message at the registration desk to collect your badge.", "vi": "Email xác nhận sẽ được gửi sau khi khoản thanh toán của bạn được xử lý. Vui lòng xuất trình email này tại bàn đăng ký để nhận thẻ."}], "glossary": {"registration": "việc đăng ký", "participants": "người tham dự", "discount": "giảm giá", "payment": "thanh toán", "organizers": "ban tổ chức", "confirmation": "sự xác nhận", "badge": "thẻ"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Chọn đáp án cho chỗ trống [131]','{"options_vi": {"A": "bởi vì (+ mệnh đề)", "B": "do (+ danh từ)", "C": "mặc dù", "D": "trừ khi"}, "explanation": "Sau chỗ trống là cụm danh từ the limited number of seats. Because of + danh từ chỉ nguyên nhân; các phương án còn lại cần mệnh đề."}',131 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:3]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=131);
