INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',6,'Part 6 — Cấp 4','[READING_PART6_LEVEL:4] Chọn đủ 4 câu của bài đọc để xem kết quả.','HARD',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:4]%');
INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:4]%' ORDER BY id LIMIT 1),'{"title": "Equipment Safety Review", "lines": [{"en": "MEMORANDUM · To: Production staff · Subject: Equipment inspection", "vi": "BẢN GHI NHỚ · Gửi: Nhân viên sản xuất · Chủ đề: Kiểm tra thiết bị"}, {"en": "Following last week’s inspection, the supervisor recommended that every machine [131] before use.", "vi": "Sau đợt kiểm tra tuần trước, người giám sát đề nghị mọi máy đều được kiểm tra trước khi sử dụng."}, {"en": "The instructions [132] to this notice describe the new procedure. Please read them before your next shift.", "vi": "Hướng dẫn được đính kèm thông báo này mô tả quy trình mới. Vui lòng đọc trước ca làm tiếp theo."}, {"en": "The company is committed to [133] workplace accidents through regular training.", "vi": "Công ty cam kết giảm tai nạn lao động thông qua đào tạo định kỳ."}, {"en": "Only certified technicians may repair the equipment. [134] Instead, report any faults to the maintenance desk.", "vi": "Chỉ kỹ thuật viên có chứng chỉ mới được sửa thiết bị. Không được tự sửa chữa. Thay vào đó, hãy báo lỗi cho bộ phận bảo trì."}], "glossary": {"inspection": "cuộc kiểm tra", "supervisor": "người giám sát", "procedure": "quy trình", "shift": "ca làm việc", "certified": "có chứng chỉ", "faults": "các lỗi", "maintenance": "bảo trì"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:4]%' ORDER BY id LIMIT 1) AND sort_order=1);
