INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',6,'Part 6 — Cấp 5','[READING_PART6_LEVEL:5] Chọn đủ 4 câu của bài đọc để xem kết quả.','HARD',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%');
INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1),'{"title": "Supplier Contract Renewal", "lines": [{"en": "To: Procurement committee · Subject: Renewal of supply agreement", "vi": "Gửi: Hội đồng mua sắm · Chủ đề: Gia hạn thỏa thuận cung ứng"}, {"en": "The supplier’s proposal, [131] financial implications were initially unclear, has now been reviewed by the finance team.", "vi": "Đề xuất của nhà cung cấp, có các tác động tài chính ban đầu chưa rõ, hiện đã được nhóm tài chính xem xét."}, {"en": "[132] approval from both parties, the agreement may be extended for two years.", "vi": "Với điều kiện được cả hai bên chấp thuận, thỏa thuận có thể được gia hạn hai năm."}, {"en": "Had the supplier failed the audit, we [133] an alternative partner. Fortunately, all requirements were met.", "vi": "Nếu nhà cung cấp không vượt qua kiểm toán, chúng ta đã phải tìm một đối tác khác. May mắn là mọi yêu cầu đều được đáp ứng."}, {"en": "The revised agreement includes a clause allowing us to terminate it if delivery standards are repeatedly missed. [134] Please review the final draft before Friday.", "vi": "Thỏa thuận sửa đổi có điều khoản cho phép chấm dứt nếu tiêu chuẩn giao hàng liên tục không được đáp ứng. Quy định này giúp bảo vệ chúng ta khỏi các gián đoạn kéo dài. Vui lòng xem bản dự thảo cuối trước thứ Sáu."}], "glossary": {"procurement": "hoạt động mua sắm của tổ chức", "proposal": "đề xuất", "implications": "các hệ quả; tác động", "agreement": "thỏa thuận", "audit": "cuộc kiểm toán", "clause": "điều khoản", "terminate": "chấm dứt", "disruptions": "sự gián đoạn"}}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1);
INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Chọn đáp án cho chỗ trống [131]','{"options_vi": {"A": "cái mà", "B": "người mà (tân ngữ)", "C": "mà", "D": "có ... (sở hữu)"}, "explanation": "Whose chỉ quan hệ sở hữu giữa proposal và financial implications, có thể dùng cho vật. That không dùng trong mệnh đề không xác định; which không trực tiếp chỉ sở hữu."}',131 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=131);
