INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1),(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1),'Chọn đáp án cho chỗ trống [134]','{"options_vi": {"A": "Quy định này giúp bảo vệ chúng ta khỏi gián đoạn kéo dài.", "B": "Văn phòng nhà cung cấp ở gần sân bay.", "C": "Hội đồng họp trong phòng ở tầng ba.", "D": "Danh mục trước có bốn mươi trang."}, "explanation": "This provision liên kết trực tiếp với điều khoản chấm dứt hợp đồng ở câu trước và giải thích lợi ích của nó. Các lựa chọn khác làm đứt mạch nội dung."}',134 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND passage_id=(SELECT id FROM practice_passages WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=6 AND instructions LIKE '[READING_PART6_LEVEL:5]%' ORDER BY id LIMIT 1) AND sort_order=1 ORDER BY id LIMIT 1) AND sort_order=134);
